CREATE TABLE users (
  id TEXT PRIMARY KEY,
  organization_id TEXT,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  phone TEXT NOT NULL,
  age INTEGER,
  gender TEXT,
  occupation TEXT,
  organization TEXT,
  emergency_contact_name TEXT,
  emergency_contact_phone TEXT,
  emergency_contact_relation TEXT,
  city TEXT,
  is_profile_completed INTEGER NOT NULL DEFAULT 0,
  role TEXT NOT NULL,
  avatar TEXT,
  property_id TEXT,
  property_name TEXT,
  room_number TEXT,
  staff_role TEXT,
