  assigned_properties TEXT, -- JSON array
  permissions TEXT, password_hash TEXT, email_verified INTEGER NOT NULL DEFAULT 0, phone_verified INTEGER NOT NULL DEFAULT 0, aadhaar_last4 TEXT, aadhaar_hash TEXT, permanent_address TEXT, alternate_phone TEXT, profile_extras TEXT, -- JSON object
  FOREIGN KEY (organization_id) REFERENCES organizations(id)
);
