CREATE TABLE attendance_records (
  id TEXT PRIMARY KEY,
  person_id TEXT NOT NULL,
  person_name TEXT NOT NULL,
  person_type TEXT NOT NULL,
  room_number TEXT,
  role TEXT,
  date TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  type TEXT NOT NULL,
  status TEXT NOT NULL,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE staff_members (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  role TEXT NOT NULL,
  phone TEXT NOT NULL,
  avatar TEXT,
  property_id TEXT NOT NULL,
  shift TEXT NOT NULL,
  today_status TEXT NOT NULL DEFAULT 'Checked-Out',
  last_clock_in TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')), owner_user_id TEXT, organization_id TEXT,
  FOREIGN KEY (property_id) REFERENCES properties(id)
);
CREATE TABLE staff_tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  category TEXT NOT NULL,
  assigned_to_name TEXT NOT NULL,
  time_slot TEXT NOT NULL,
  priority TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE broadcast_notifications (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  category TEXT NOT NULL,
  target TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  sender TEXT NOT NULL,
  read INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE meal_plans (
  id TEXT PRIMARY KEY,
  day TEXT NOT NULL UNIQUE,
  breakfast TEXT NOT NULL,
  lunch TEXT NOT NULL,
  snacks TEXT NOT NULL,
  dinner TEXT NOT NULL,
  special_note TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE chat_messages (
  id TEXT PRIMARY KEY,
  sender_role TEXT NOT NULL,
  sender_name TEXT NOT NULL,
  recipient_name TEXT NOT NULL,
  text TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  is_owner INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE maintenance_tickets (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  room_number TEXT NOT NULL,
  resident_name TEXT NOT NULL,
  description TEXT NOT NULL,
  priority TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Reported',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  assigned_staff_name TEXT,
  sla_deadline TEXT,
  photo_url TEXT,
  cost REAL,
  resolution_notes TEXT
);
CREATE TABLE leads (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT NOT NULL,
  property_id TEXT,
  property_name TEXT,
  room_type_preference TEXT NOT NULL,
  budget_max INTEGER NOT NULL,
  budget INTEGER NOT NULL,
  preferred_move_in TEXT,
  expected_move_in_date TEXT NOT NULL,
  stage TEXT NOT NULL DEFAULT 'New Lead',
  source TEXT NOT NULL,
  assigned_to TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_follow_up TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (property_id) REFERENCES properties(id)
);
CREATE TABLE electricity_meter_readings (
  id TEXT PRIMARY KEY,
  property_id TEXT NOT NULL,
  property_name TEXT NOT NULL,
  room_number TEXT NOT NULL,
  meter_number TEXT NOT NULL,
  previous_reading REAL NOT NULL,
  current_reading REAL NOT NULL,
  units_consumed REAL NOT NULL,
  rate_per_unit REAL NOT NULL,
  fixed_charges REAL NOT NULL,
  total_amount REAL NOT NULL,
  reading_date TEXT NOT NULL,
  staff_name TEXT NOT NULL,
  meter_photo_url TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Verified',
  is_anomaly INTEGER NOT NULL DEFAULT 0,
  anomaly_reason TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (property_id) REFERENCES properties(id)
);
CREATE TABLE security_deposit_records (
  id TEXT PRIMARY KEY,
  resident_id TEXT NOT NULL,
  resident_name TEXT NOT NULL,
  room_number TEXT NOT NULL,
  property_id TEXT NOT NULL,
  deposit_received REAL NOT NULL,
  received_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Held',
  deductions TEXT, -- JSON array
  total_deductions REAL NOT NULL DEFAULT 0,
  final_refund_amount REAL NOT NULL,
  refund_date TEXT,
  refund_transaction_id TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (resident_id) REFERENCES residents(id),
  FOREIGN KEY (property_id) REFERENCES properties(id)
);
CREATE TABLE rent_agreements (
  id TEXT PRIMARY KEY,
  agreement_number TEXT NOT NULL UNIQUE,
  resident_id TEXT NOT NULL,
  resident_name TEXT NOT NULL,
  parent_guardian_name TEXT,
  tenant_dob TEXT NOT NULL,
  tenant_permanent_address TEXT NOT NULL,
  tenant_current_address TEXT NOT NULL,
  tenant_college_or_office TEXT NOT NULL,
  tenant_id_document_type TEXT NOT NULL,
  tenant_id_document_masked TEXT NOT NULL,
  property_id TEXT NOT NULL,
  property_name TEXT NOT NULL,
  property_address TEXT NOT NULL,
  owner_name TEXT NOT NULL,
  owner_phone TEXT NOT NULL,
  room_number TEXT NOT NULL,
  bed_number TEXT NOT NULL,
  monthly_rent REAL NOT NULL,
  security_deposit REAL NOT NULL,
  electricity_terms TEXT NOT NULL,
  notice_period_days INTEGER NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  rules_summary TEXT, -- JSON array
  emergency_contact_name TEXT NOT NULL,
  emergency_contact_phone TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Draft',
  owner_signed INTEGER NOT NULL DEFAULT 0,
  tenant_signed INTEGER NOT NULL DEFAULT 0,
  signed_date TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (resident_id) REFERENCES residents(id),
  FOREIGN KEY (property_id) REFERENCES properties(id)
);
CREATE TABLE visitor_passes (
  id TEXT PRIMARY KEY,
  resident_id TEXT NOT NULL,
  resident_name TEXT NOT NULL,
  room_number TEXT NOT NULL,
  visitor_name TEXT NOT NULL,
  visitor_phone TEXT NOT NULL,
  purpose TEXT NOT NULL,
  expected_arrival TEXT NOT NULL,
  check_in_time TEXT,
  check_out_time TEXT,
  status TEXT NOT NULL DEFAULT 'Pre-Approved',
  approved_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (resident_id) REFERENCES residents(id)
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  user_name TEXT NOT NULL,
  user_role TEXT NOT NULL,
  action TEXT NOT NULL,
  entity TEXT NOT NULL,
  entity_id TEXT,
  timestamp TEXT NOT NULL,
  details TEXT NOT NULL, -- JSON object
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
